/** Índice por id — usado em todas as buscas por exercício salvo. */
export const POR_ID: Record<string, Exercicio> = Object.fromEntries(
  EXERCICIOS.map((e) => [e.id, e]),
);

const CDN = 'https://cdn.jsdelivr.net/gh/yuhonas/free-exercise-db@main/exercises';

/** Quadro `n` (0 = início, 1 = fim) da demonstração do exercício. */
export function quadroUrl(ex: Exercicio | undefined, n: 0 | 1): string | null {
  if (!ex?.img) return null;
  return `${CDN}/${ex.img}/${n}.jpg`;
}

/** Remove acentos e caixa para tornar a busca tolerante à digitação. */
export function normalizar(s: string): string {
  return s
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .trim();
}

const INDICE_BUSCA = EXERCICIOS.map((e) => ({
  id: e.id,
  chave: normalizar(`${e.nome} ${e.grupo} ${e.equip}`),
}));

export function buscar(termo: string): Exercicio[] {
  const t = normalizar(termo);
  if (!t) return EXERCICIOS;
  const termos = t.split(/\s+/);
  return INDICE_BUSCA.filter((i) => termos.every((p) => i.chave.includes(p))).map(
    (i) => POR_ID[i.id],
  );
}
